"""Render the detail pages under README/DOCS from meta/project.json.

The root README is a short landing page. Everything that used to grow there
lives on these pages, and each page is built from the same metadata so the
landing summary and the detail text can never drift apart.
"""

from __future__ import annotations

import re
from typing import Any, Dict, Iterable, Sequence

MARKER = (
    "<!-- Generated by scripts/build_readme.py from meta/project.json. "
    "Do not edit by hand. -->"
)

FEATURES_PAGE = "features"
SUPPORTED_PAGES = (
    FEATURES_PAGE,
    "install",
    "usage",
    "language-server",
    "safety",
    "development",
)

_FOOTER = "[Back to FuzzySurgical](../../README.md)"
_HEADING_RE = re.compile(r"^(#{1,6})\s+(.*\S)\s*$")


def slug(text: str) -> str:
    """Return the anchor GitHub assigns to a heading."""

    value = text.strip().lower()
    value = re.sub(r"[^\w\s-]", "", value)
    value = re.sub(r"[\s_]+", "-", value)
    return re.sub(r"-{2,}", "-", value).strip("-")


def anchors(text: str) -> set:
    """Return every heading anchor and explicit id in a markdown document."""

    found = set()
    for line in text.splitlines():
        heading = _HEADING_RE.match(line)
        if heading:
            found.add(slug(heading.group(2)))
        found.update(re.findall(r'<a id="([^"]+)"', line))
    return found


def table(headers: Sequence[str], rows: Iterable[Sequence[Any]]) -> str:
    lines = [
        "| " + " | ".join(_cell(header) for header in headers) + " |",
        "| " + " | ".join("---" for _ in headers) + " |",
    ]
    for row in rows:
        lines.append("| " + " | ".join(_cell(cell) for cell in row) + " |")
    return "\n".join(lines)


def bullets(items: Iterable[str]) -> str:
    return "\n".join(f"- {item}" for item in items)


def code_block(language: str, commands: Sequence[str]) -> str:
    return "```" + language + "\n" + "\n".join(commands) + "\n```"


def _cell(value: Any) -> str:
    return str(value).replace("|", "\\|").replace("\n", " ").strip()


def _page(title: str, body: Sequence[str]) -> str:
    lines = [MARKER, "", _FOOTER, "", f"# {title}", ""]
    lines.extend(body)
    return _finish(lines)


def _finish(lines: Sequence[str]) -> str:
    text = "\n".join(lines).rstrip() + "\n"
    return text.replace("\n\n\n", "\n\n")


def _render_features(metadata: Dict[str, Any]) -> str:
    body = [str(metadata["summary"]).strip(), ""]
    for feature in metadata["features"]:
        body.extend([f"## {feature['title']}", "", feature["summary"], ""])
        body.extend([bullets(feature["items"]), ""])
    return _page("Features", body)


def _render_install(metadata: Dict[str, Any]) -> str:
    section = metadata["install"]
    body = [str(section.get("intro", "")).strip(), ""]
    for block in section["blocks"]:
        body.extend([f"## {block['title']}", ""])
        body.append(code_block(block.get("language", "bash"), block["commands"]))
        body.append("")
        notes = block.get("notes", [])
        if notes:
            body.extend([bullets(notes), ""])
        options = block.get("options", [])
        if options:
            body.extend(["Installer options:", ""])
            body.append(
                bullets(f"`{item['command']}`: {item['description']}" for item in options)
            )
            body.append("")

    platforms = metadata["platforms"]
    body.extend(["## Platforms", "", str(platforms["intro"]).strip(), ""])
    body.append(
        table(
            ["Platform", "Notes"],
            [[item["name"], item["notes"]] for item in platforms["items"]],
        )
    )
    body.extend(["", "## Requirements", ""])
    body.append(table(["Component", "Requirement"], metadata["requirements"]))
    return _page("Install", body)


def _render_usage(metadata: Dict[str, Any]) -> str:
    quickstart = metadata["quickstart"]
    cli = metadata["cli"]
    body = ["## Quick start", "", str(quickstart.get("intro", "")).strip(), ""]
    body.append(code_block("bash", quickstart["commands"]))
    body.extend(["", "## Command line", "", str(cli.get("intro", "")).strip(), ""])
    body.append(table(cli["columns"], cli["rows"]))
    body.extend(["", "## TUI controls", ""])
    for group in metadata["controls"]:
        body.extend([f"### {group['view']}", "", table(["Key", "Action"], group["items"]), ""])
    return _page("Usage", body)


def _render_language_server(metadata: Dict[str, Any]) -> str:
    section = metadata.get("devbox") or {}
    body = [str(section.get("intro", "")).strip(), ""]
    if section.get("example"):
        if section.get("example_path"):
            body.extend([f"`{section['example_path']}`", ""])
        body.extend([code_block(section.get("language", "json"), section["example"]), ""])
    if section.get("servers"):
        body.extend([table(["Language", "Server", "Linter"], section["servers"]), ""])
    notes = section.get("notes", [])
    if notes:
        body.extend([bullets(notes), ""])
    return _page("Language server and dev box", body)


def _render_safety(metadata: Dict[str, Any]) -> str:
    section = metadata["safety"]
    body = [str(section.get("intro", "")).strip(), ""]
    body.append(table(["Limit", "Default"], section["limits"]))
    body.append("")
    notes = section.get("notes", [])
    if notes:
        body.extend([bullets(notes), ""])
    return _page("Safety and limits", body)


def _render_development(metadata: Dict[str, Any]) -> str:
    section = metadata["development"]
    community = metadata["community"]
    body = [str(section.get("intro", "")).strip(), ""]
    body.extend(["Linux and macOS:", "", code_block("bash", section["commands"]), ""])
    body.extend(
        ["Windows PowerShell:", "", code_block("powershell", section["windows_commands"]), ""]
    )

    docker = section.get("docker")
    if docker:
        body.extend(["## Docker", "", str(docker.get("intro", "")).strip(), ""])
        if docker.get("commands"):
            body.extend([code_block("bash", docker["commands"]), ""])
        if docker.get("windows_commands"):
            body.extend(
                [
                    "Windows PowerShell host:",
                    "",
                    code_block("powershell", docker["windows_commands"]),
                    "",
                ]
            )
        if docker.get("notes"):
            body.extend([bullets(docker["notes"]), ""])

    if section.get("notes"):
        body.extend([bullets(section["notes"]), ""])

    body.extend(
        [
            "## README and documentation",
            "",
            "The landing page and every page under README/DOCS are generated from "
            "meta/project.json. Edit the JSON, then regenerate and verify before "
            "committing.",
            "",
            code_block(
                "bash",
                ["python3 scripts/build_readme.py", "python3 scripts/build_readme.py --check"],
            ),
            "",
            "- The check fails when a generated page is stale, when a relative link or "
            "anchor does not resolve, or when the version in meta/project.json does not "
            "match fuzzy_surgical/__init__.py.",
            "- Detailed content belongs in meta/project.json, which renders into "
            "README/DOCS, so the root README stays a short landing page.",
            "",
            "## Contributing",
            "",
            str(community.get("intro", "")).strip(),
            "",
            str(community.get("security", "")).strip(),
            "",
        ]
    )
    return _page("Development", body)


_RENDERERS = {
    FEATURES_PAGE: _render_features,
    "install": _render_install,
    "usage": _render_usage,
    "language-server": _render_language_server,
    "safety": _render_safety,
    "development": _render_development,
}


def render_docs(metadata: Dict[str, Any]) -> Dict[str, str]:
    """Render every page named in metadata['docs'] keyed by repository path."""

    documents: Dict[str, str] = {}
    for entry in metadata["docs"]:
        renderer = _RENDERERS.get(entry["page"])
        if renderer is None:
            raise KeyError(entry["page"])
        documents[entry["path"]] = renderer(metadata)
    return documents
